// registration.component.ts
import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators, AbstractControl, ValidationErrors } from '@angular/forms';

function passwordStrength(control: AbstractControl): ValidationErrors | null {
  const value = control.value || '';
  const hasLetter = /[A-Za-z]/.test(value);
  const hasNumber = /\d/.test(value);
  const valid = value.length >= 8 && hasLetter && hasNumber;
  return valid ? null : { passwordStrength: true };
}

function matchValidator(controlName: string, matchingControlName: string) {
  return (group: AbstractControl): ValidationErrors | null => {
    const control = group.get(controlName);
    const matchingControl = group.get(matchingControlName);
    if (control?.value !== matchingControl?.value) {
      matchingControl?.setErrors({ mustMatch: true });
      return { mustMatch: true };
    }
    matchingControl?.setErrors(null);
    return null;
  };
}

@Component({...})
export class RegistrationComponent {
  form: FormGroup;

  constructor(private fb: FormBuilder) {
    this.form = this.fb.group({
      firstName: ['', Validators.required],
      lastName: ['', Validators.required],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, passwordStrength]],
      confirmPassword: ['', Validators.required]
    }, { validators: matchValidator('password', 'confirmPassword') });
  }

  onSubmit() {
    if (this.form.valid) {
      console.log(this.form.value);
      this.form.reset();
    }
  }
}

// registration.component.html (excerpt)
<form [formGroup]="form" (ngSubmit)="onSubmit()">
  <input formControlName="firstName" placeholder="First name">
  <div *ngIf="form.get('firstName')?.invalid && form.get('firstName')?.touched">Required</div>
  <!-- similar for other fields -->
  <input formControlName="password" type="password" placeholder="Password">
  <div *ngIf="form.get('password')?.errors?.passwordStrength && form.get('password')?.touched">
    Password must be 8+ chars with letter and number.
  </div>
  <input formControlName="confirmPassword" type="password" placeholder="Confirm password">
  <div *ngIf="form.errors?.mustMatch && form.get('confirmPassword')?.touched">
    Passwords do not match.
  </div>
  <button type="submit" [disabled]="!form.valid">Register</button>
</form>
